import React, { useCallback } from 'react';
import PropTypes from 'prop-types';

import MonacoEditor from './MonacoEditor.jsx';

const MonacoEditorContainer = ({
  editorActions,
  editorSelectors,
  isReadOnly = false,
  bracketPairColorizationEnabled = false,
  EditorContentOrigin,
}) => {
  const theme = editorSelectors.selectTheme();
  const value = editorSelectors.selectContent();
  const language = editorSelectors.selectLanguage();

  const handleEditorDidMount = useCallback(
    (editor) => {
      editor.focus();
      editorActions.editorSetup(editor, 'monaco');
    },
    [editorActions]
  );

  const handleEditorWillUnmount = useCallback(
    (editor) => {
      editorActions.editorTearDown(editor, 'monaco');
    },
    [editorActions]
  );

  const handleChangeEditorValue = useCallback(
    (newValue) => {
      editorActions.setContentDebounced(newValue, EditorContentOrigin.Editor);
    },
    [editorActions, EditorContentOrigin]
  );

  const handleEditorMarkersDidChange = useCallback(
    (markers) => {
      editorActions.setMarkers(markers);
    },
    [editorActions]
  );

  return (
    <MonacoEditor
      language={language}
      theme={theme}
      value={value}
      isReadOnly={isReadOnly}
      bracketPairColorizationEnabled={bracketPairColorizationEnabled}
      onChange={handleChangeEditorValue}
      onMount={handleEditorDidMount}
      onWillUnmount={handleEditorWillUnmount}
      onEditorMarkersDidChange={handleEditorMarkersDidChange}
    />
  );
};

MonacoEditorContainer.propTypes = {
  isReadOnly: PropTypes.bool,
  bracketPairColorizationEnabled: PropTypes.bool,
  editorActions: PropTypes.shape({
    editorSetup: PropTypes.func.isRequired,
    editorTearDown: PropTypes.func.isRequired,
    setContentDebounced: PropTypes.func.isRequired,
    setMarkers: PropTypes.func.isRequired,
  }).isRequired,
  editorSelectors: PropTypes.shape({
    selectLanguage: PropTypes.func.isRequired,
    selectContent: PropTypes.func.isRequired,
    selectTheme: PropTypes.func.isRequired,
  }).isRequired,
  EditorContentOrigin: PropTypes.shape({
    Editor: PropTypes.string.isRequired,
  }).isRequired,
};

export default MonacoEditorContainer;

import React, { useEffect } from 'react';
import PropTypes from 'prop-types';

const Parsing = () => <div>Parsing...</div>;

const EditorPreviewAPIDesignSystems = ({
  getComponent,
  editorPreviewADSActions,
  editorPreviewADSSelectors,
}) => {
  const Main = getComponent('ADSMain', true);
  const ParseErrors = getComponent('EditorPreviewAPIDesignSystemsParseErrors', true);
  const isParseInProgress = editorPreviewADSSelectors.selectIsParseInProgress();
  const isParseSuccess = editorPreviewADSSelectors.selectIsParseSuccess();
  const isParseFailure = editorPreviewADSSelectors.selectIsParseFailure();
  const parseError = editorPreviewADSSelectors.selectParseError();

  useEffect(() => {
    return () => {
      editorPreviewADSActions.previewUnmounted();
    };
  }, [editorPreviewADSActions]);

  return (
    <section className="swagger-editor__editor-preview-api-design-systems">
      {isParseInProgress && <Parsing />}
      {isParseSuccess && <Main />}
      {isParseFailure && <ParseErrors error={parseError} />}
    </section>
  );
};

EditorPreviewAPIDesignSystems.propTypes = {
  getComponent: PropTypes.func.isRequired,
  editorPreviewADSActions: PropTypes.shape({
    previewUnmounted: PropTypes.func.isRequired,
  }).isRequired,
  editorPreviewADSSelectors: PropTypes.shape({
    selectIsParseInProgress: PropTypes.func.isRequired,
    selectIsParseSuccess: PropTypes.func.isRequired,
    selectIsParseFailure: PropTypes.func.isRequired,
    selectParseResult: PropTypes.func.isRequired,
    selectParseError: PropTypes.func.isRequired,
    selectMainElement: PropTypes.func.isRequired,
  }).isRequired,
};

export default EditorPreviewAPIDesignSystems;

